-- =============================================================================
-- Bhalojob database schema (PostgreSQL 18)
--
-- Based on オブジェクト定義書, with these changes:
--   * Every table has a numeric `id` primary key. Relationships use it.
--   * The 12-digit member numbers (10yymm000001 / 20yymm000001) are kept as
--     unique display numbers, generated by sequences. This replaces 採番マスタ.
--   * 技人国 / 特定技能 / 技能実習 wishes share one table (`track` column),
--     and so do the three study wishes (`school_category` column).
--   * Contact requests are stored (applications), not only emailed.
--   * Photos, logos and videos are stored in file storage (S3); the database
--     keeps only the file key.
--   * Passwords are NOT stored here. The login library adds its own tables.
--
-- First Prisma migration (baseline). Apply with `npm run db:deploy`; never edit
-- it after it has been applied anywhere. Later changes go in new migrations.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- Choice lists (enums)
-- -----------------------------------------------------------------------------
CREATE TYPE account_type       AS ENUM ('individual', 'corporate', 'staff');
CREATE TYPE corporation_kind   AS ENUM ('company', 'school');
CREATE TYPE job_track          AS ENUM ('engineer', 'ssw', 'titp');           -- 技人国 / 特定技能 / 技能実習
CREATE TYPE school_category    AS ENUM ('university', 'vocational', 'language_school');
CREATE TYPE university_level   AS ENUM ('undergraduate', 'graduate');          -- 大学 / 大学院
CREATE TYPE ssw_test_status    AS ENUM ('passed', 'in_progress', 'not_taken'); -- 合格 / 受験中 / 未受験
CREATE TYPE application_status AS ENUM ('new', 'in_progress', 'closed');

-- Member number sequences (replace 採番マスタ).
CREATE SEQUENCE individual_member_seq;
CREATE SEQUENCE corporate_member_seq;

-- Keeps updated_at current on every UPDATE.
CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

-- =============================================================================
-- 1. Login
-- =============================================================================

-- One row per login. Replaces ログインマスタ and ユーザマスタ.
CREATE TABLE users (
  id             uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  email          varchar(254) NOT NULL UNIQUE,
  email_verified boolean      NOT NULL DEFAULT false,
  name           varchar(80),
  account_type   account_type NOT NULL,
  is_active      boolean      NOT NULL DEFAULT true,
  last_login_at  timestamptz,
  created_at     timestamptz  NOT NULL DEFAULT now(),
  updated_at     timestamptz  NOT NULL DEFAULT now()
);

-- Admin console permissions (ユーザマスタ). Only for account_type = 'staff'.
CREATE TABLE staff_profiles (
  user_id    uuid        PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  is_admin   boolean     NOT NULL DEFAULT false,
  can_view   boolean     NOT NULL DEFAULT true,
  can_edit   boolean     NOT NULL DEFAULT false,
  can_delete boolean     NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- 2. Individual members (個人会員)
-- =============================================================================

CREATE TABLE individuals (
  id                 bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id            uuid        NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  member_no          char(12)    NOT NULL UNIQUE
                       DEFAULT ('10' || to_char(now(), 'YYMM') || lpad(nextval('individual_member_seq')::text, 6, '0')),
  -- 基本情報 (BHALO010)
  full_name          varchar(80) NOT NULL,
  name_kana          varchar(120),            -- フリガナ (needed on the 履歴書)
  gender             varchar(20),
  birth_date         date,
  has_spouse         boolean,
  has_children       boolean,
  children_count     smallint    CHECK (children_count >= 0),
  -- 住所情報 (BHALO011)
  residence_country  varchar(80),
  nationality        varchar(80),
  native_language    varchar(80),
  mobile             varchar(20),
  contact_email      varchar(254),
  postal_code        varchar(20),
  state              varchar(50),
  city               varchar(50),
  street             varchar(50),
  house_number       varchar(20),
  -- 画像 / VISA / 自己紹介 / 動画 (BHALO012, 013, 018, 210)
  photo_key          varchar(300),
  visa_status        varchar(40),
  visa_expiry        date,       -- first day of the expiry month
  introduction       text        CHECK (char_length(introduction) <= 4000),
  appeal_video_key   varchar(300),
  -- 求職希望・留学希望 (BHALO019)
  wants_engineer        boolean NOT NULL DEFAULT false,
  wants_ssw             boolean NOT NULL DEFAULT false,
  wants_titp            boolean NOT NULL DEFAULT false,
  wants_university      boolean NOT NULL DEFAULT false,
  wants_vocational      boolean NOT NULL DEFAULT false,
  wants_language_school boolean NOT NULL DEFAULT false,
  is_active          boolean     NOT NULL DEFAULT true,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now()
);

-- 言語 (BHALO014)
CREATE TABLE individual_languages (
  id            bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id bigint      NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  language      varchar(30) NOT NULL,
  level         varchar(20),
  sort_order    smallint    NOT NULL DEFAULT 0
);

-- 学歴 (BHALO015)
CREATE TABLE individual_educations (
  id            bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id bigint      NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  degree        varchar(80),
  school_name   varchar(120),
  enrolled_on   date,       -- year + month, stored as the 1st of the month
  graduated_on  date,
  passed_on     date,
  major         varchar(80),
  sort_order    smallint    NOT NULL DEFAULT 0
);

-- 実務経験 (BHALO016)
CREATE TABLE individual_work_experiences (
  id            bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id bigint       NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  company_name  varchar(80),
  industry      varchar(120),
  joined_on     date,
  left_on       date,
  sort_order    smallint     NOT NULL DEFAULT 0,
  CHECK (left_on IS NULL OR joined_on IS NULL OR left_on >= joined_on)
);

-- 認定資格 (BHALO017)
CREATE TABLE individual_certifications (
  id                bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id     bigint       NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  name              varchar(120) NOT NULL,
  certificate_title varchar(120),
  acquired_on       date,
  sort_order        smallint     NOT NULL DEFAULT 0
);

-- 希望地域 (BHALO020)
CREATE TABLE individual_preferred_areas (
  id            bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id bigint       NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  country       varchar(120),
  region        varchar(120),
  prefecture    varchar(120),
  city          varchar(120),
  free_text     varchar(300),
  sort_order    smallint     NOT NULL DEFAULT 0
);

-- 技人国 / 特定技能 / 技能実習 wishes (BHALO021–023)
CREATE TABLE individual_job_wishes (
  id              bigint          GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id   bigint          NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  track           job_track       NOT NULL,
  desired_job     varchar(120),
  desired_salary  varchar(80),
  years_of_stay   smallint        CHECK (years_of_stay BETWEEN 0 AND 99),
  ssw_test        ssw_test_status,
  notes           varchar(300),
  sort_order      smallint        NOT NULL DEFAULT 0,
  CHECK (ssw_test IS NULL OR track = 'ssw')   -- the exam only applies to 特定技能
);

-- 大学・大学院 / 専門学校 / 日本語学校 wishes (BHALO024–026)
CREATE TABLE individual_study_wishes (
  id               bigint           GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id    bigint           NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  school_category  school_category  NOT NULL,
  university_level university_level,
  school_name      varchar(120),
  faculty          varchar(120),
  department       varchar(120),
  notes            varchar(300),
  sort_order       smallint         NOT NULL DEFAULT 0,
  CHECK (university_level IS NULL OR school_category = 'university')
);

-- 履歴書 (BHALO201). One per individual.
CREATE TABLE resumes (
  individual_id bigint       PRIMARY KEY REFERENCES individuals(id) ON DELETE CASCADE,
  height_cm     numeric(4,1) CHECK (height_cm > 0),
  weight_kg     numeric(4,1) CHECK (weight_kg > 0),
  blood_type    varchar(8),
  dominant_hand varchar(10),
  eyesight_right numeric(3,1),
  eyesight_left  numeric(3,1),
  smokes        boolean,
  has_tattoo    boolean,
  tattoo_location varchar(50),
  passport_no   varchar(100),  -- store ENCRYPTED by the app, never plain text
  alcohol       varchar(60),
  allergies     varchar(60),
  religion      varchar(80),   -- 要配慮個人情報: needs explicit consent (APPI)
  strengths     varchar(200),
  weaknesses    varchar(200),
  motivation    varchar(300),
  hobbies       varchar(200),
  other_notes   varchar(300),
  -- When the candidate agreed to share religion / health data (APPI 要配慮個人情報).
  sensitive_consent_at timestamptz,
  created_at    timestamptz  NOT NULL DEFAULT now(),
  updated_at    timestamptz  NOT NULL DEFAULT now()
);

-- 家族構成 (BHALO202)
CREATE TABLE family_members (
  id            bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id bigint       NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  relation      varchar(50),
  full_name     varchar(80),
  birth_date    date,
  address       varchar(120),
  occupation    varchar(80),
  sort_order    smallint     NOT NULL DEFAULT 0
);

-- =============================================================================
-- 3. Corporate members (法人会員: companies and schools)
-- =============================================================================

CREATE TABLE corporations (
  id               bigint           GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id          uuid             NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  member_no        char(12)         NOT NULL UNIQUE
                     DEFAULT ('20' || to_char(now(), 'YYMM') || lpad(nextval('corporate_member_seq')::text, 6, '0')),
  kind             corporation_kind NOT NULL,
  -- 基本情報1 (BHALO111 / 151)
  name             varchar(120)     NOT NULL,
  name_kana        varchar(120),
  founded          varchar(50),
  representative   varchar(80)      NOT NULL,
  capital_man_yen  integer          CHECK (capital_man_yen >= 0),  -- 万円
  headcount        integer          CHECK (headcount >= 0),        -- 従業員数・生徒数
  industry         varchar(120),
  url              varchar(200),
  -- 基本情報2 (BHALO112 / 152)
  postal_code      varchar(20),
  prefecture       varchar(50),
  city             varchar(50),
  town             varchar(50),
  address_line     varchar(50),
  contact_person   varchar(80),
  phone            varchar(20),
  contact_email    varchar(254),
  -- ロゴ / 紹介文 (BHALO113–114 / 153–154)
  logo_key         varchar(300),
  introduction     text             CHECK (char_length(introduction) <= 4000),
  -- 対象選択 (BHALO110)
  is_company               boolean NOT NULL DEFAULT false,
  is_supervising_org       boolean NOT NULL DEFAULT false,  -- 監理団体
  is_registered_support_org boolean NOT NULL DEFAULT false, -- 登録支援機関
  is_university            boolean NOT NULL DEFAULT false,
  is_vocational_school     boolean NOT NULL DEFAULT false,
  is_language_school       boolean NOT NULL DEFAULT false,
  is_active        boolean          NOT NULL DEFAULT true,
  created_at       timestamptz      NOT NULL DEFAULT now(),
  updated_at       timestamptz      NOT NULL DEFAULT now(),
  CHECK (is_company OR is_supervising_org OR is_registered_support_org
         OR is_university OR is_vocational_school OR is_language_school)
);

-- 求人情報 (BHALO116)
CREATE TABLE job_postings (
  id              bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  corporation_id  bigint       NOT NULL REFERENCES corporations(id) ON DELETE CASCADE,
  job_no          integer      NOT NULL,         -- 1, 2, 3 … within the company
  track           job_track    NOT NULL,
  industry        varchar(120),
  job_type        varchar(120),
  work_name       varchar(120),
  employment_type varchar(120),
  description     varchar(1000),
  location        varchar(120),
  hours_from      time,
  hours_to        time,
  holidays        varchar(120),
  monthly_salary  integer      CHECK (monthly_salary >= 0),  -- 円/月
  contact_person  varchar(80),
  contact_email   varchar(254),
  features        varchar(1000),                 -- 会社の特長
  is_active       boolean      NOT NULL DEFAULT true,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  updated_at      timestamptz  NOT NULL DEFAULT now(),
  UNIQUE (corporation_id, job_no)
);

-- 求人票 (BHALO117). One per job posting.
CREATE TABLE job_orders (
  job_posting_id            bigint      PRIMARY KEY REFERENCES job_postings(id) ON DELETE CASCADE,
  daily_working_time        time,       -- 1日の労働時間 (hh:mm)
  overtime_daily_hours      smallint,
  overtime_monthly_avg_hours smallint,
  break_time                varchar(120),
  avg_work_days_per_month   smallint,
  annual_work_hours         smallint,
  weekly_work_days          varchar(120),
  has_employment_insurance  boolean     NOT NULL DEFAULT false,  -- 雇用保険
  has_workers_comp          boolean     NOT NULL DEFAULT false,  -- 労災保険
  has_health_insurance      boolean     NOT NULL DEFAULT false,  -- 健康保険
  has_pension               boolean     NOT NULL DEFAULT false,  -- 厚生年金
  commute_full              boolean     NOT NULL DEFAULT false,  -- 通勤手当 全額支給
  commute_fixed             boolean     NOT NULL DEFAULT false,  -- 通勤手当 一律
  japanese_level            varchar(120),
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now()
);

-- 生徒募集情報 (BHALO156)
CREATE TABLE recruitments (
  id              bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  corporation_id  bigint       NOT NULL REFERENCES corporations(id) ON DELETE CASCADE,
  recruitment_no  integer      NOT NULL,
  faculty         varchar(120),
  department      varchar(120),
  school_gender   varchar(20),                  -- 共学 / 男子校 / 女子校
  location        varchar(120),
  capacity        integer      CHECK (capacity >= 0),
  annual_tuition  integer      CHECK (annual_tuition >= 0),  -- 円/年
  contact_person  varchar(80),
  contact_email   varchar(254),
  notes           varchar(300),
  is_active       boolean      NOT NULL DEFAULT true,
  created_at      timestamptz  NOT NULL DEFAULT now(),
  updated_at      timestamptz  NOT NULL DEFAULT now(),
  UNIQUE (corporation_id, recruitment_no)
);

-- =============================================================================
-- 4. Contact requests (コンタクト申込, BHALO200)
-- =============================================================================

CREATE TABLE applications (
  id            bigint             GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  individual_id bigint             NOT NULL REFERENCES individuals(id) ON DELETE CASCADE,
  status        application_status NOT NULL DEFAULT 'new',
  staff_note    text,
  created_at    timestamptz        NOT NULL DEFAULT now(),
  updated_at    timestamptz        NOT NULL DEFAULT now()
);

-- Each item points at exactly one job posting OR one recruitment.
CREATE TABLE application_items (
  id             bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  application_id bigint NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
  job_posting_id bigint REFERENCES job_postings(id) ON DELETE SET NULL,
  recruitment_id bigint REFERENCES recruitments(id) ON DELETE SET NULL,
  -- Snapshot so the request still makes sense if the posting is deleted later.
  target_label   varchar(300) NOT NULL,
  CHECK (num_nonnulls(job_posting_id, recruitment_id) <= 1)
);

-- =============================================================================
-- 5. Master data and settings
-- =============================================================================

-- 選択項目マスタ. Two levels via parent_id (業種 → 職種, 言語 → レベル, 学部 → 学科).
CREATE TABLE selection_options (
  id         bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  category   varchar(40) NOT NULL,                -- e.g. 'industry', 'visa', 'country'
  parent_id  bigint      REFERENCES selection_options(id) ON DELETE CASCADE,
  label_ja   varchar(120) NOT NULL,
  label_en   varchar(120),
  label_bn   varchar(120),
  sort_order smallint    NOT NULL DEFAULT 0,
  is_active  boolean     NOT NULL DEFAULT true
);

-- 人気業種
CREATE TABLE popular_industries (
  id         bigint       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  label_ja   varchar(60)  NOT NULL,
  label_en   varchar(120),
  sort_order smallint     NOT NULL DEFAULT 0
);

-- 管理マスタ: key/value settings such as where contact requests are emailed.
CREATE TABLE site_settings (
  key        varchar(80) PRIMARY KEY,
  value      text        NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Who in the staff looked at or changed what (needed for personal data under APPI).
CREATE TABLE audit_logs (
  id           bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  staff_user_id uuid       REFERENCES users(id) ON DELETE SET NULL,
  action       varchar(40) NOT NULL,             -- 'view', 'create', 'update', 'delete'
  target_table varchar(60) NOT NULL,
  target_id    varchar(40) NOT NULL,
  details      jsonb,
  created_at   timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- 6. Indexes (foreign keys and common searches)
-- =============================================================================

CREATE INDEX ON individual_languages        (individual_id);
CREATE INDEX ON individual_educations       (individual_id);
CREATE INDEX ON individual_work_experiences (individual_id);
CREATE INDEX ON individual_certifications   (individual_id);
CREATE INDEX ON individual_preferred_areas  (individual_id);
CREATE INDEX ON individual_job_wishes       (individual_id);
CREATE INDEX ON individual_study_wishes     (individual_id);
CREATE INDEX ON family_members              (individual_id);
CREATE INDEX ON applications                (individual_id);
CREATE INDEX ON applications                (status, created_at DESC);
CREATE INDEX ON application_items           (application_id);
CREATE INDEX ON application_items           (job_posting_id);
CREATE INDEX ON application_items           (recruitment_id);
CREATE INDEX ON selection_options           (category, parent_id, sort_order);
CREATE INDEX ON audit_logs                  (target_table, target_id);

-- My Page job search: active postings by track and industry.
CREATE INDEX ON job_postings (track, industry) WHERE is_active;
CREATE INDEX ON recruitments (corporation_id)  WHERE is_active;
-- Admin dashboard: newest members.
CREATE INDEX ON individuals  (created_at DESC);
CREATE INDEX ON corporations (kind, created_at DESC);

-- =============================================================================
-- 7. updated_at triggers
-- =============================================================================

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'users', 'staff_profiles', 'individuals', 'resumes', 'corporations',
    'job_postings', 'job_orders', 'recruitments', 'applications', 'site_settings'
  ] LOOP
    EXECUTE format(
      'CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION set_updated_at()',
      t || '_set_updated_at', t);
  END LOOP;
END;
$$;
